/* Local-only experiment. Production hosts cannot enable it with a URL parameter. */
(function(root){
'use strict';
const local=['localhost','127.0.0.1','[::1]'].includes(root.location?.hostname),enabled=local&&new URLSearchParams(root.location?.search||'').get('features')?.split(',').includes('gamification');
function dateKey(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');}
function createTracker(saved={},legacy=[]){
 const data={records:{},sessions:{},...saved};data.records=data.records&&typeof data.records==='object'?data.records:{};data.sessions=data.sessions&&typeof data.sessions==='object'?data.sessions:{};
 const old=new Set(legacy);
 return {data,begin(record,dailyDate=null){data.sessions[record.id]={help:false,level:record.level,dailyDate};},assist(id){if(data.sessions[id])data.sessions[id].help=true;},finish(record,date=dateKey()){
  const session=data.sessions[record.id];if(old.has(record.id)||data.records[record.id])return false;
  data.records[record.id]={level:record.level,help:session?session.help:null,date,dailyDate:session?.dailyDate||null};return true;
 },summary(){const records=Object.values(data.records),ids=new Set([...old,...Object.keys(data.records)]);return {total:ids.size,without:records.filter(r=>r.help===false).length,withHelp:records.filter(r=>r.help===true).length,unknown:[...old].filter(id=>!data.records[id]).length+records.filter(r=>r.help===null).length,levels:new Set(records.map(r=>r.level)).size,days:[...new Set(records.filter(r=>r.dailyDate).map(r=>r.date))]};}};
}
if(typeof module!=='undefined')module.exports={createTracker,dateKey};
if(!enabled||typeof document==='undefined')return;
let saved={},legacy=[];try{saved=JSON.parse(localStorage.getItem('sudoku-progress-preview-v1')||'{}');legacy=JSON.parse(localStorage.getItem('sudoku-library-v1')||'{}').completed||[];}catch{}
const tracker=createTracker(saved,legacy);let active=null,storageOK=true;
function persist(){try{localStorage.setItem('sudoku-progress-preview-v1',JSON.stringify(tracker.data));}catch{storageOK=false;}}
const button=document.createElement('button');button.type='button';button.id='my-progress';button.textContent='Moje postępy · test';button.className='secondary';document.querySelector('.header-preferences').append(button);
const dialog=document.createElement('dialog');dialog.id='progress-dialog';dialog.innerHTML='<form method="dialog"><button class="close" aria-label="Zamknij">×</button></form><p class="eyebrow">LOKALNY PROTOTYP</p><h2>Moje postępy</h2><p class="progress-total"></p><div class="progress-stats"></div><h3>Małe osiągnięcia</h3><ul class="progress-badges"></ul><h3 class="progress-month">Sudoku dnia — ten miesiąc</h3><div class="progress-calendar"></div><p class="help">● Ukończone Sudoku dnia na dowolnym poziomie. Zaznaczamy lokalny dzień ukończenia łamigłówki dnia.</p><p class="help">Bez podpowiedzi: bez ujawniania techniki i bez oznaczania błędów. Obliczanie kandydatów i wypełnianie pojedynczych to zwykłe narzędzia. Wcześniejsze ukończenia mają nieznany sposób rozwiązania. Każda plansza jest liczona raz; ponowne rozwiązanie nie zmienia kategorii.</p><p class="progress-storage help"></p>';
document.body.append(dialog);
function paint(){const s=tracker.summary();dialog.querySelector('.progress-total').textContent=`${s.total} / 10 000 ukończonych plansz`;dialog.querySelector('.progress-stats').replaceChildren(...[[s.without,'Bez podpowiedzi'],[s.withHelp,'Z pomocą'],[s.unknown,'Wcześniejsze — brak danych']].map(([n,label])=>{const el=document.createElement('div');el.textContent=`${n} · ${label}`;return el;}));dialog.querySelector('.progress-badges').replaceChildren(...[[s.total>=1,'Pierwsza plansza'],[s.total>=10,'Dziesięć ukończonych'],[s.levels===4,'Każdy poziom trudności']].map(([done,label])=>{const el=document.createElement('li');el.textContent=`${done?'✓':'○'} ${label}`;return el;}));const now=new Date(),days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();dialog.querySelector('.progress-month').textContent='Sudoku dnia — '+new Intl.DateTimeFormat('pl',{month:'long',year:'numeric'}).format(now);dialog.querySelector('.progress-calendar').replaceChildren(...['Pn','Wt','Śr','Cz','Pt','So','Nd'].map(day=>{const el=document.createElement('b');el.textContent=day;return el;}),...Array.from({length:(new Date(now.getFullYear(),now.getMonth(),1).getDay()+6)%7},()=>document.createElement('i')),...Array.from({length:days},(_,i)=>{const el=document.createElement('span'),key=dateKey(new Date(now.getFullYear(),now.getMonth(),i+1)),done=s.days.includes(key);el.textContent=`${i+1}${done?' ●':''}`;el.className=done?'day-done':'';el.setAttribute('aria-label',`${key}${done?' — ukończone Sudoku dnia':''}`);return el;}));dialog.querySelector('.progress-storage').textContent=storageOK?'Dane testowe na tym urządzeniu. Bez konta, synchronizacji i zmian na produkcji.':'Nie udało się zapisać postępów. Dane działają tylko w tej sesji.';}
button.onclick=()=>{paint();dialog.showModal();};
root.SudokuProgress={begin(record,dailyDate){tracker.begin(record,dailyDate);persist();},assist(){if(active){tracker.assist(active.id);persist();}},onBoard(record,solved,options={}){active=record;if(!record)return;if(options.errors)tracker.assist(record.id);if(solved)tracker.finish(record);persist();}};
})(globalThis);
